"""Budget and cleanup checks in disposable fixtures, without compiling Basalgrim."""

import contextlib
import importlib.util
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest
from unittest.mock import patch

spec = importlib.util.spec_from_file_location("cargo_local", Path(__file__).with_name("cargo_local.py"))
cargo_local = importlib.util.module_from_spec(spec)
spec.loader.exec_module(cargo_local)


class BudgetTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Use a tag generated by the installed Cargo, including its clean safety
        # checks. This compiles only one empty disposable crate, never Basalgrim.
        with tempfile.TemporaryDirectory(prefix="basalgrim-cache-tag-") as tmp:
            seed = Path(tmp)
            (seed / "src").mkdir()
            (seed / "src/lib.rs").write_text("")
            (seed / "Cargo.toml").write_text('[package]\nname="cache-tag"\nversion="0.0.0"\nedition="2024"\n')
            subprocess.run(["cargo", "check", "--offline"], cwd=seed, check=True, capture_output=True,
                           env=dict(os.environ, CARGO_TARGET_DIR=str(seed / "target"),
                                    CARGO_BUILD_BUILD_DIR=str(seed / "target")))
            cls.cache_tag = (seed / "target/CACHEDIR.TAG").read_bytes()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="basalgrim-cache-test-")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        (self.root / "src").mkdir()
        (self.root / "src/lib.rs").write_text("")
        (self.root / "Cargo.toml").write_text('[package]\nname="cache-fixture"\nversion="0.0.0"\n')
        (self.root / "keep.txt").write_text("source must survive")
        (self.root / "target").mkdir()
        (self.root / "target/CACHEDIR.TAG").write_bytes(self.cache_tag)
        (self.root / "bin").mkdir()
        real_cargo = shutil.which("cargo")
        fake = self.root / "bin/cargo"
        fake.write_text('''#!/usr/bin/env python3
import json,os,pathlib,subprocess,sys,time
root=pathlib.Path.cwd();target=pathlib.Path(os.environ["CARGO_TARGET_DIR"])
if sys.argv[1]=="clean":
    with (root/"clean-calls").open("a") as log:log.write("clean\\n")
    sys.exit(subprocess.call([REAL_CARGO,*sys.argv[1:]]))
target.mkdir(exist_ok=True)
(root/"args.json").write_text(json.dumps(sys.argv[1:]))
mode=sys.argv[1]
if mode=="grow-child":
    peer=subprocess.Popen([sys.executable,"-c",'import os,pathlib,signal,time;signal.signal(signal.SIGTERM,signal.SIG_IGN);pathlib.Path("peer.pid").write_text(str(os.getpid()));time.sleep(30)'])
    while not (root/"peer.pid").exists():time.sleep(.001)
if mode in ("burst","grow","grow-child"):
    (target/"big").write_bytes(b"a"*(2*1024*1024))
if mode in ("grow","grow-child"):time.sleep(30)
sys.exit(7 if mode=="fail" else 0)
'''.replace("REAL_CARGO", repr(real_cargo)))
        fake.chmod(0o755)
        changes = (
            patch.object(cargo_local, "ROOT", self.root),
            patch.object(cargo_local, "TARGET", self.root / "target"),
            patch.object(cargo_local, "BUDGET", 1024 * 1024),
            patch.object(cargo_local, "INTERVAL", 0.05),
            patch.dict(os.environ, {"PATH": str(self.root / "bin") + os.pathsep + os.environ["PATH"]}),
        )
        for change in changes:
            change.start()
            self.addCleanup(change.stop)

    def run_cargo(self, *args):
        with contextlib.redirect_stderr(io.StringIO()):
            result = cargo_local.main(args)
        self.assertEqual((self.root / "keep.txt").read_text(), "source must survive")
        return result

    def test_existing_oversized_cache_is_cleaned_before_command(self):
        target = self.root / "target"
        (target / "stale").write_bytes(b"a" * (2 * 1024 * 1024))
        self.assertEqual(self.run_cargo("build"), 0)
        self.assertFalse((target / "stale").exists())
        self.assertTrue((self.root / "clean-calls").exists())

    def test_completed_oversized_output_is_cleaned_and_not_reported_as_success(self):
        self.assertEqual(self.run_cargo("burst"), 75)
        self.assertLessEqual(cargo_local.target_bytes(), cargo_local.BUDGET)

    def test_running_command_is_stopped_and_oversized_output_cleaned(self):
        self.assertEqual(self.run_cargo("grow"), 75)
        self.assertLessEqual(cargo_local.target_bytes(), cargo_local.BUDGET)

    def test_descendant_ignoring_sigterm_is_stopped_before_cleanup(self):
        self.assertEqual(self.run_cargo("grow-child"), 75)
        pid = int((self.root / "peer.pid").read_text())
        status = Path(f"/proc/{pid}/status")
        if status.exists():
            self.assertIn("State:\tZ", status.read_text())
        self.assertLessEqual(cargo_local.target_bytes(), cargo_local.BUDGET)

    def test_cargo_exit_code_and_program_arguments_are_preserved(self):
        self.assertEqual(self.run_cargo("fail"), 7)
        self.assertEqual(self.run_cargo("run", "--", "--target-dir", "app-argument"), 0)
        self.assertEqual(json.loads((self.root / "args.json").read_text()),
                         ["run", "--", "--target-dir", "app-argument"])
        self.assertFalse((self.root / "clean-calls").exists())

    def test_target_symlink_and_output_override_are_rejected(self):
        outside = self.root / "outside"
        outside.mkdir()
        (outside / "keep").write_text("outside")
        shutil.rmtree(self.root / "target")
        (self.root / "target").symlink_to(outside, target_is_directory=True)
        with self.assertRaisesRegex(RuntimeError, "symlink"):
            self.run_cargo("build")
        with self.assertRaisesRegex(RuntimeError, "overrides"):
            self.run_cargo("build", "--target-dir=outside")
        self.assertEqual((outside / "keep").read_text(), "outside")

    def test_concurrent_wrapper_is_rejected_without_cleanup(self):
        with (self.root / ".basalgrim-cargo.lock").open("w") as lock:
            cargo_local.fcntl.flock(lock, cargo_local.fcntl.LOCK_EX)
            with self.assertRaisesRegex(RuntimeError, "another"):
                self.run_cargo("build")
        self.assertFalse((self.root / "clean-calls").exists())

    def test_allocated_size_counts_hard_links_once_and_skips_symlink_targets(self):
        target = self.root / "target"
        (target / "one").write_bytes(b"x" * 20000)
        os.link(target / "one", target / "two")
        (target / "external").symlink_to(self.root, target_is_directory=True)
        expected = sum(p.lstat().st_blocks * 512 for p in
                       (target, target / "one", target / "external", target / "CACHEDIR.TAG"))
        self.assertEqual(cargo_local.target_bytes(), expected)


if __name__ == "__main__":
    unittest.main()
